// ===== TYPING EFFECT =====
const phrases = [
  "Étudiant en Réseaux & Télécommunications",
  "Développeur Web — HTML / CSS / JS",
  "Programmeur C / C++ / Python",
  "Passionné de systèmes embarqués"
];
let pIdx = 0, cIdx = 0, deleting = false;
const typingEl = document.getElementById('typing-text');

function type() {
  const phrase = phrases[pIdx];
  typingEl.textContent = deleting
    ? phrase.substring(0, cIdx--)
    : phrase.substring(0, cIdx++);

  if (!deleting && cIdx > phrase.length) {
    deleting = true;
    setTimeout(type, 1800);
    return;
  }
  if (deleting && cIdx < 0) {
    deleting = false;
    pIdx = (pIdx + 1) % phrases.length;
  }
  setTimeout(type, deleting ? 40 : 70);
}
type();

// ===== SCROLL FADE-IN + SKILL BARS =====
const fadeEls = document.querySelectorAll('.fade-in');
const bars    = document.querySelectorAll('.bar-fill');

const observer = new IntersectionObserver((entries) => {
  entries.forEach(entry => {
    if (!entry.isIntersecting) return;
    entry.target.classList.add('visible');
    // Animate skill bars inside visible section
    entry.target.querySelectorAll('.bar-fill').forEach(bar => {
      bar.style.width = bar.dataset.w + '%';
    });
    observer.unobserve(entry.target);
  });
}, { threshold: 0.1 });

fadeEls.forEach(el => observer.observe(el));

// ===== NAVBAR SHRINK ON SCROLL =====
const navbar = document.getElementById('navbar');
window.addEventListener('scroll', () => {
  navbar.classList.toggle('scrolled', window.scrollY > 50);
});

// ===== BURGER MENU =====
const burger    = document.getElementById('burger');
const navLinks  = document.querySelector('.nav-links');

burger.addEventListener('click', () => {
  navLinks.classList.toggle('open');
  // Animate burger
  const spans = burger.querySelectorAll('span');
  if (navLinks.classList.contains('open')) {
    spans[0].style.transform = 'rotate(45deg) translate(5px, 5px)';
    spans[1].style.opacity   = '0';
    spans[2].style.transform = 'rotate(-45deg) translate(5px, -5px)';
  } else {
    spans.forEach(s => { s.style.transform = ''; s.style.opacity = ''; });
  }
});

// Close nav on link click
navLinks.querySelectorAll('a').forEach(a => {
  a.addEventListener('click', () => {
    navLinks.classList.remove('open');
    burger.querySelectorAll('span').forEach(s => {
      s.style.transform = ''; s.style.opacity = '';
    });
  });
});

// ===== PARTICLES =====
const canvas = document.getElementById('particles');
const ctx    = canvas.getContext('2d');

function resize() {
  canvas.width  = window.innerWidth;
  canvas.height = window.innerHeight;
}
resize();
window.addEventListener('resize', resize);

const N = 70;
const pts = Array.from({ length: N }, () => ({
  x:  Math.random() * canvas.width,
  y:  Math.random() * canvas.height,
  r:  Math.random() * 1.5 + 0.5,
  dx: (Math.random() - 0.5) * 0.4,
  dy: (Math.random() - 0.5) * 0.4
}));

function draw() {
  ctx.clearRect(0, 0, canvas.width, canvas.height);
  pts.forEach(p => {
    p.x += p.dx;
    p.y += p.dy;
    if (p.x < 0 || p.x > canvas.width)  p.dx *= -1;
    if (p.y < 0 || p.y > canvas.height) p.dy *= -1;
    ctx.beginPath();
    ctx.arc(p.x, p.y, p.r, 0, Math.PI * 2);
    ctx.fillStyle = 'rgba(0,245,212,0.5)';
    ctx.fill();
  });
  for (let i = 0; i < N; i++) {
    for (let j = i + 1; j < N; j++) {
      const d = Math.hypot(pts[i].x - pts[j].x, pts[i].y - pts[j].y);
      if (d < 130) {
        ctx.beginPath();
        ctx.moveTo(pts[i].x, pts[i].y);
        ctx.lineTo(pts[j].x, pts[j].y);
        ctx.strokeStyle = `rgba(0,245,212,${(1 - d / 130) * 0.25})`;
        ctx.lineWidth = 0.4;
        ctx.stroke();
      }
    }
  }
  requestAnimationFrame(draw);
}
draw();

// ===== CV DOWNLOAD — PDF embarqué =====
const CV_B64 = '';

function downloadCV() {
  const bytes = atob(CV_B64);
  const arr = new Uint8Array(bytes.length);
  for (let i = 0; i < bytes.length; i++) arr[i] = bytes.charCodeAt(i);
  const blob = new Blob([arr], { type: 'application/pdf' });
  const url  = URL.createObjectURL(blob);
  const link = document.createElement('a');
  link.href     = url;
  link.download = 'Sanou_Isaac_CV.pdf';
  link.click();
  setTimeout(() => URL.revokeObjectURL(url), 1000);
}

['dl-cv-nav','dl-cv-hero','dl-cv-contact'].forEach(id => {
  const el = document.getElementById(id);
  if (el) el.addEventListener('click', e => { e.preventDefault(); downloadCV(); });
});